def unflatten_tuple_keys(d):
    def insert(root, path, value):
        if len(path) == 1:
            root[path[0]] = value
            return
        key = path[0]
        if key not in root or not isinstance(root[key], dict):
            root[key] = {}
        insert(root[key], path[1:], value)
    result = {}
    for path, value in d.items():
        insert(result, path, value)
    return result

