def find_pairs_summing_to(lst, target):
    from itertools import combinations
    result = []
    for i, j in combinations(range(len(lst)), 2):
        if lst[i] + lst[j] == target:
            result.append([i, j])
    return result

def first_repeating_char(s):
    seen = set()
    dupes = set()
    for ch in s:
        if ch in seen:
            dupes.add(ch)
        else:
            seen.add(ch)
    for ch in s:
        if ch in dupes:
            return ch
    return None

