import math

def count_common_divisors(a, b):
    g = math.gcd(a, b)
    divisors = set()
    d = 1
    while d * d <= g:
        if g % d == 0:
            divisors.add(d)
            divisors.add(g // d)
        d += 1
    return len(divisors)

